theorem hasDerivAt_det {M : ℝ → Matrix (Fin n) (Fin n) ℝ} {M' : Matrix (Fin n) (Fin n) ℝ} {t : ℝ}
    (h : ∀ i j, HasDerivAt (fun s => M s i j) (M' i j) t) :
    HasDerivAt (fun s => (M s).det) (∑ i, ∑ j, cofSum (M t) i j * M' i j) t

